from itertools import permutations

def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if any(char not in ['(', ')'] for string in lst for char in string):
        return 'No'

    left_count = sum(string.count('(') for string in lst)
    right_count = sum(string.count(')') for string in lst)

    if left_count != right_count:
        return 'No'

    for perm in permutations(lst):
        if is_balanced(''.join(perm)):
            return 'Yes'

    return 'No'

